// Strong symbols (initialized globals, functions)
int strong_var = 42;        // Strong: initialized
void strong_func() {}       // Strong: function definition

// Weak symbols (uninitialized globals)
int weak_var;               // Weak: uninitialized (BSS)

// Explicit weak symbol with attribute
__attribute__((weak)) void default_handler() {
    // Default implementation
}

// Strong overrides weak
void default_handler() {    // Strong: overrides weak
    // Custom implementation wins
}

// Linker resolution rules:
// 1. Strong + Strong = ERROR (multiple definition)
// 2. Strong + Weak   = Strong wins
// 3. Weak + Weak     = Pick one arbitrarily

// Check symbol types with nm:
// $ nm file.o
// 0000000000000000 T strong_func    # T = strong text
// 0000000000000000 D strong_var     # D = strong data
// 0000000000000000 W default_handler # W = weak
// 0000000000000004 C weak_var       # C = common (weak)
